-- ===== supabase/migrations/20261015000003_workflow_functions.sql =====
-- Database functions for multi-step saves. Each one runs as a single transaction, so a
-- save either fully happens or does not happen at all. The Next.js server checks the
-- user's role first; these functions check it again as a second line of defence.

-- Past decisions and evidence can never be changed or deleted on their own.
create or replace function public.prevent_history_change() returns trigger
language plpgsql as $$
begin
  raise exception 'history_is_read_only: % rows cannot be changed', tg_table_name;
end $$;

create trigger decisions_read_only before update on public.decisions
  for each row execute function public.prevent_history_change();
create trigger evidence_read_only before update on public.evidence_snapshots
  for each row execute function public.prevent_history_change();

-- Only draft policy versions can be edited. Active and archived versions are frozen.
create or replace function public.protect_policy_versions() returns trigger
language plpgsql as $$
begin
  if old.status <> 'draft' and new.definition is distinct from old.definition then
    raise exception 'policy_frozen: only draft versions can be edited';
  end if;
  if old.status = 'archived' and new.status <> 'archived' then
    raise exception 'policy_frozen: archived versions cannot be reactivated, copy them into a new draft';
  end if;
  return new;
end $$;

create trigger policy_versions_protect before update on public.policy_versions
  for each row execute function public.protect_policy_versions();

create or replace function public.actor_role(p_actor uuid) returns text
language sql stable as $$
  select role from public.app_users where id = p_actor
$$;

-- Create a request together with its first decision, evidence snapshot and events.
-- Calling it twice with the same idempotency key returns the first request.
create or replace function public.create_request(p jsonb) returns jsonb
language plpgsql as $$
declare
  v_key uuid := (p->>'idempotency_key')::uuid;
  v_actor uuid := (p->>'actor_id')::uuid;
  v_req jsonb := p->'request';
  v_dec jsonb := p->'decision';
  v_id uuid;
  v_decision_id uuid;
  v_role text;
begin
  v_role := public.actor_role(v_actor);
  if v_role is null then
    raise exception 'forbidden: unknown user';
  end if;

  select id into v_id from public.requests where idempotency_key = v_key;
  if v_id is not null then
    return jsonb_build_object('id', v_id, 'duplicate', true);
  end if;

  insert into public.requests (
    request_type, money_involved, amount_cents, complaint_status, welfare_status, reference_id,
    booking_id, context, confirmed_facts, decision, decision_reason, matched_rule_id, policy_version,
    policy_version_id, next_step, status, intake_method, idempotency_key, created_by
  ) values (
    v_req->>'request_type', v_req->>'money_involved', (v_req->>'amount_cents')::integer,
    v_req->>'complaint_status', v_req->>'welfare_status', v_req->>'reference_id', v_req->>'booking_id',
    coalesce(v_req->>'context', ''), v_req->'confirmed_facts', v_req->>'decision', v_req->>'decision_reason',
    v_req->>'matched_rule_id', v_req->>'policy_version', (v_req->>'policy_version_id')::uuid,
    coalesce(v_req->>'next_step', ''), v_req->>'status', p->>'intake_method', v_key, v_actor
  )
  on conflict (idempotency_key) do nothing
  returning id into v_id;

  if v_id is null then
    -- Another identical submission won the race. Return that one.
    select id into v_id from public.requests where idempotency_key = v_key;
    return jsonb_build_object('id', v_id, 'duplicate', true);
  end if;

  insert into public.decisions (
    request_id, sequence, colour, matched_rule_id, policy_version, policy_version_id, policy_snapshot,
    facts, result, input_hash, engine_version, reason, created_by
  ) values (
    v_id, 1, v_dec->>'colour', v_dec->>'matched_rule_id', v_dec->>'policy_version',
    (v_dec->>'policy_version_id')::uuid, v_dec->'policy_snapshot', v_dec->'facts', v_dec->'result',
    v_dec->>'input_hash', v_dec->>'engine_version', 'initial', v_actor
  ) returning id into v_decision_id;

  insert into public.evidence_snapshots (decision_id, request_id, records, retrieved_at)
  values (v_decision_id, v_id, p->'evidence', (p->'evidence'->>'retrievedAt')::timestamptz);

  update public.requests set current_decision_id = v_decision_id where id = v_id;

  insert into public.request_events (request_id, event_type, actor_id, actor_role, to_status, note)
  values (v_id, 'created', v_actor, v_role, v_req->>'status',
          format('Saved with decision %s (%s, %s)', v_req->>'decision', v_req->>'matched_rule_id', v_req->>'policy_version'));

  -- Link any agent activity from the intake session to the new request.
  if p ? 'session_key' then
    update public.ai_activity set request_id = v_id
    where session_key = (p->>'session_key')::uuid and request_id is null;
    update public.ai_activity set state = 'completed', summary = 'The admin confirmed the facts and submitted them.'
    where session_key = (p->>'session_key')::uuid and event_type = 'confirmation_required' and state = 'pending';
  end if;

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (v_actor, v_role, 'request.create', 'request', v_id::text,
          jsonb_build_object('decision', v_req->>'decision', 'rule', v_req->>'matched_rule_id'));

  return jsonb_build_object('id', v_id, 'duplicate', false);
end $$;

-- Re-run the engine after Sarah clarifies facts. The earlier decision stays in history.
-- expected_decision_id stops two people (or two clicks) from re-evaluating at once.
create or replace function public.reevaluate_request(p jsonb) returns jsonb
language plpgsql as $$
declare
  v_id uuid := (p->>'request_id')::uuid;
  v_actor uuid := (p->>'actor_id')::uuid;
  v_req jsonb := p->'request';
  v_dec jsonb := p->'decision';
  v_role text;
  v_old record;
  v_seq integer;
  v_decision_id uuid;
begin
  v_role := public.actor_role(v_actor);
  if v_role is null then raise exception 'forbidden: unknown user'; end if;

  select * into v_old from public.requests where id = v_id for update;
  if not found then raise exception 'not_found'; end if;
  if v_old.current_decision_id is distinct from (p->>'expected_decision_id')::uuid then
    raise exception 'stale_update: this request changed since you opened it';
  end if;
  if v_old.status not in ('needs_clarification', 'review_required', 'more_info_requested') then
    raise exception 'invalid_transition: facts can only be updated while clarification is open';
  end if;

  select coalesce(max(sequence), 0) + 1 into v_seq from public.decisions where request_id = v_id;

  insert into public.decisions (
    request_id, sequence, colour, matched_rule_id, policy_version, policy_version_id, policy_snapshot,
    facts, result, input_hash, engine_version, reason, created_by
  ) values (
    v_id, v_seq, v_dec->>'colour', v_dec->>'matched_rule_id', v_dec->>'policy_version',
    (v_dec->>'policy_version_id')::uuid, v_dec->'policy_snapshot', v_dec->'facts', v_dec->'result',
    v_dec->>'input_hash', v_dec->>'engine_version', 'clarification', v_actor
  ) returning id into v_decision_id;

  insert into public.evidence_snapshots (decision_id, request_id, records, retrieved_at)
  values (v_decision_id, v_id, p->'evidence', (p->'evidence'->>'retrievedAt')::timestamptz);

  update public.requests set
    money_involved = v_req->>'money_involved',
    amount_cents = (v_req->>'amount_cents')::integer,
    complaint_status = v_req->>'complaint_status',
    welfare_status = v_req->>'welfare_status',
    reference_id = v_req->>'reference_id',
    booking_id = v_req->>'booking_id',
    context = coalesce(v_req->>'context', ''),
    confirmed_facts = v_req->'confirmed_facts',
    decision = v_req->>'decision',
    decision_reason = v_req->>'decision_reason',
    matched_rule_id = v_req->>'matched_rule_id',
    policy_version = v_req->>'policy_version',
    policy_version_id = (v_req->>'policy_version_id')::uuid,
    next_step = coalesce(v_req->>'next_step', ''),
    status = v_req->>'status',
    current_decision_id = v_decision_id,
    decision_count = v_seq,
    updated_at = now()
  where id = v_id;

  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (v_id, case when v_old.status = 'more_info_requested' then 'admin_replied' else 'reevaluated' end,
          v_actor, v_role, v_old.status, v_req->>'status',
          coalesce(nullif(p->>'note', ''), format('Re-evaluated: %s (%s)', v_req->>'decision', v_req->>'matched_rule_id')));

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (v_actor, v_role, 'request.reevaluate', 'request', v_id::text,
          jsonb_build_object('from', v_old.decision, 'to', v_req->>'decision', 'sequence', v_seq));

  return jsonb_build_object('id', v_id, 'decision_id', v_decision_id, 'sequence', v_seq);
end $$;

-- Move a request through the workflow. Owner approvals change only this request's
-- status. They never touch policies or the original decision.
create or replace function public.transition_request(
  p_request_id uuid, p_actor uuid, p_action text, p_note text
) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_from text[];
  v_to text;
  v_event text;
  v_owner_only boolean := false;
  v_old_status text;
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if coalesce(btrim(p_note), '') = '' then raise exception 'reason_required: a note or reason is required'; end if;
  if char_length(p_note) > 4000 then raise exception 'invalid_input: note is too long'; end if;

  case p_action
    when 'send_to_owner' then
      v_from := array['review_required', 'needs_clarification', 'more_info_requested']; v_to := 'awaiting_owner'; v_event := 'sent_to_owner';
    when 'approve' then
      v_from := array['awaiting_owner']; v_to := 'approved'; v_event := 'owner_approved'; v_owner_only := true;
    when 'decline' then
      v_from := array['awaiting_owner']; v_to := 'declined'; v_event := 'owner_declined'; v_owner_only := true;
    when 'request_info' then
      v_from := array['awaiting_owner']; v_to := 'more_info_requested'; v_event := 'owner_requested_info'; v_owner_only := true;
    when 'record_and_close' then
      v_from := array['ready', 'approved', 'declined']; v_to := 'closed'; v_event := 'closed';
    else
      raise exception 'invalid_input: unknown action %', p_action;
  end case;

  if v_owner_only and v_role <> 'owner' then
    raise exception 'forbidden: only the owner can do this';
  end if;

  select status into v_old_status from public.requests where id = p_request_id for update;
  if not found then raise exception 'not_found'; end if;

  -- The status check and the update happen together, so a second click finds the
  -- status already changed and does nothing.
  update public.requests set status = v_to, updated_at = now()
  where id = p_request_id and status = any (v_from);
  if not found then
    raise exception 'invalid_transition: cannot % a request that is %', p_action, v_old_status;
  end if;

  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (p_request_id, v_event, p_actor, v_role, v_old_status, v_to, p_note);

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'request.' || p_action, 'request', p_request_id::text,
          jsonb_build_object('from', v_old_status, 'to', v_to));

  return jsonb_build_object('id', p_request_id, 'status', v_to);
end $$;

-- Create a new draft policy version. Version numbers are allocated under a lock.
create or replace function public.create_policy_draft(
  p_actor uuid, p_category text, p_definition jsonb, p_note text, p_source text
) returns jsonb
language plpgsql as $$
declare
  v_version integer;
  v_id uuid;
begin
  if public.actor_role(p_actor) is distinct from 'owner' then
    raise exception 'forbidden: only the owner can create rule drafts';
  end if;
  perform pg_advisory_xact_lock(hashtext('policy:' || p_category));
  select coalesce(max(version), 0) + 1 into v_version from public.policy_versions where category = p_category;
  insert into public.policy_versions (category, version, status, definition, change_note, source, created_by)
  values (p_category, v_version, 'draft', p_definition, coalesce(p_note, ''), p_source, p_actor)
  returning id into v_id;
  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, 'owner', 'policy.create_draft', 'policy_version', v_id::text,
          jsonb_build_object('category', p_category, 'version', v_version, 'source', p_source));
  return jsonb_build_object('id', v_id, 'version', v_version);
end $$;

-- Activate a validated draft. The previous active version is archived, not deleted.
create or replace function public.activate_policy_version(
  p_version_id uuid, p_actor uuid, p_note text
) returns jsonb
language plpgsql as $$
declare
  v_row public.policy_versions;
  v_previous uuid;
begin
  if public.actor_role(p_actor) is distinct from 'owner' then
    raise exception 'forbidden: only the owner can activate rules';
  end if;
  select * into v_row from public.policy_versions where id = p_version_id for update;
  if not found then raise exception 'not_found'; end if;
  if v_row.status <> 'draft' then
    raise exception 'invalid_transition: only draft versions can be activated';
  end if;
  perform pg_advisory_xact_lock(hashtext('policy:' || v_row.category));

  update public.policy_versions set status = 'archived', archived_at = now()
  where category = v_row.category and status = 'active'
  returning id into v_previous;

  update public.policy_versions
  set status = 'active', activated_by = p_actor, activated_at = now(),
      change_note = case when coalesce(p_note, '') = '' then change_note else p_note end
  where id = p_version_id;

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, 'owner', 'policy.activate', 'policy_version', p_version_id::text,
          jsonb_build_object('category', v_row.category, 'version', v_row.version, 'archived', v_previous));
  return jsonb_build_object('id', p_version_id, 'archived', v_previous);
end $$;

-- Only the server (service role) may call these functions.
revoke all on function public.create_request(jsonb) from public, anon, authenticated;
revoke all on function public.reevaluate_request(jsonb) from public, anon, authenticated;
revoke all on function public.transition_request(uuid, uuid, text, text) from public, anon, authenticated;
revoke all on function public.create_policy_draft(uuid, text, jsonb, text, text) from public, anon, authenticated;
revoke all on function public.activate_policy_version(uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.actor_role(uuid) from public, anon, authenticated;
grant execute on function public.create_request(jsonb) to service_role;
grant execute on function public.reevaluate_request(jsonb) to service_role;
grant execute on function public.transition_request(uuid, uuid, text, text) to service_role;
grant execute on function public.create_policy_draft(uuid, text, jsonb, text, text) to service_role;
grant execute on function public.activate_policy_version(uuid, uuid, text) to service_role;
grant execute on function public.actor_role(uuid) to service_role;

-- ===== supabase/migrations/20261019000001_remove_from_list.sql =====
-- Lets admins and the owner take a request off the lists without deleting it.
-- The request, its decisions and its history all stay; it just stops showing on the
-- dashboard, Requests and Approval Alley. It can be put back from its own page.
alter table public.requests
  add column if not exists hidden_at timestamptz,
  add column if not exists hidden_by uuid references public.app_users (id);

alter table public.request_events drop constraint if exists request_events_event_type_check;
alter table public.request_events add constraint request_events_event_type_check check (event_type in (
  'created', 'reevaluated', 'sent_to_owner', 'owner_approved', 'owner_declined',
  'owner_requested_info', 'admin_replied', 'admin_recorded', 'closed',
  'removed_from_list', 'restored_to_list'
));

-- ===== supabase/migrations/20261019000002_hsc_catalogue.sql =====
-- NSW HSC subject catalogue (Years 11 and 12).
-- The catalogue rows come from src/lib/catalogue/hsc.ts through supabase/catalogue.sql.
-- Category codes such as MTH1011 are Tutor Compass's own codes, not NESA course numbers.
-- Every table here is safe to create again: nothing is dropped and no rows are removed.

create table if not exists public.hsc_subject_areas (
  id text primary key,
  name text not null,
  year11_code text not null unique check (year11_code ~ '^[A-Z]{3}1011$'),
  year12_code text not null unique check (year12_code ~ '^[A-Z]{3}1012$'),
  sort_order integer not null
);

create table if not exists public.hsc_courses (
  id text primary key check (id ~ '^[a-z0-9_]+$'),
  area_id text not null references public.hsc_subject_areas (id),
  name text not null,
  kind text not null check (kind in ('course', 'language', 'vet')),
  note text not null default '',
  sort_order integer not null
);

-- Which year each course actually runs in. A course and year pair must be here before
-- anyone can record it.
create table if not exists public.hsc_course_years (
  course_id text not null references public.hsc_courses (id),
  year_level smallint not null check (year_level in (11, 12)),
  primary key (course_id, year_level)
);

-- What this business actually offers, out of the full catalogue. The owner switches
-- these on and off on the Subjects page.
create table if not exists public.course_offerings (
  course_id text not null,
  year_level smallint not null,
  offered boolean not null default false,
  updated_by uuid references public.app_users (id),
  updated_at timestamptz not null default now(),
  primary key (course_id, year_level),
  foreign key (course_id, year_level) references public.hsc_course_years (course_id, year_level)
);

-- The exact courses and years each tutor teaches.
create table if not exists public.tutor_courses (
  id uuid primary key default gen_random_uuid(),
  tutor_id text not null references public.tutors (id) on delete cascade,
  course_id text not null,
  year_level smallint not null,
  area_id text,
  category_code text,
  course_level text not null default '',
  qualification text not null default '' check (char_length(qualification) <= 120),
  created_at timestamptz not null default now(),
  unique (tutor_id, course_id, year_level, course_level),
  foreign key (course_id, year_level) references public.hsc_course_years (course_id, year_level)
);

-- The courses each student is studying.
create table if not exists public.student_courses (
  id uuid primary key default gen_random_uuid(),
  family_id text not null references public.families (id) on delete cascade,
  student_name text not null check (char_length(student_name) between 1 and 80),
  course_id text not null,
  year_level smallint not null,
  area_id text,
  category_code text,
  course_level text not null default '',
  qualification text not null default '' check (char_length(qualification) <= 120),
  created_at timestamptz not null default now(),
  unique (family_id, student_name, course_id, year_level, course_level),
  foreign key (course_id, year_level) references public.hsc_course_years (course_id, year_level)
);

-- Bookings keep their old free-text subject and can also point at an exact course.
alter table public.bookings
  add column if not exists course_id text,
  add column if not exists year_level smallint,
  add column if not exists area_id text,
  add column if not exists category_code text,
  add column if not exists course_level text not null default '',
  add column if not exists qualification text not null default '';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'bookings_course_year_fk') then
    alter table public.bookings add constraint bookings_course_year_fk
      foreign key (course_id, year_level) references public.hsc_course_years (course_id, year_level);
  end if;
end $$;

-- Fills in the subject area and category code from the catalogue, so they can never
-- disagree with the course and year, and rejects levels that don't fit.
create or replace function public.hsc_fill_course() returns trigger
language plpgsql as $$
declare
  v_kind text;
  v_area text;
  v_code text;
begin
  if new.course_id is null then
    new.year_level := null; new.area_id := null; new.category_code := null;
    new.course_level := ''; new.qualification := '';
    return new;
  end if;
  select c.kind, c.area_id, case when new.year_level = 11 then a.year11_code else a.year12_code end
    into v_kind, v_area, v_code
    from public.hsc_courses c
    join public.hsc_subject_areas a on a.id = c.area_id
    join public.hsc_course_years y on y.course_id = c.id and y.year_level = new.year_level
   where c.id = new.course_id;
  if v_area is null then
    raise exception 'invalid_input: % is not a Year % course', new.course_id, new.year_level;
  end if;
  if v_kind = 'language' then
    if new.course_level not in ('beginners', 'continuers', 'extension') then
      raise exception 'invalid_input: choose Beginners, Continuers or Extension for a language';
    end if;
    if new.course_level = 'extension' and new.year_level <> 12 then
      raise exception 'invalid_input: language Extension is a Year 12 course';
    end if;
  elsif new.course_level <> '' then
    raise exception 'invalid_input: only languages have a level';
  end if;
  if v_kind <> 'vet' then new.qualification := ''; end if;
  new.area_id := v_area;
  new.category_code := v_code;
  return new;
end $$;

drop trigger if exists tutor_courses_fill on public.tutor_courses;
create trigger tutor_courses_fill before insert or update on public.tutor_courses
  for each row execute function public.hsc_fill_course();
drop trigger if exists student_courses_fill on public.student_courses;
create trigger student_courses_fill before insert or update on public.student_courses
  for each row execute function public.hsc_fill_course();
drop trigger if exists bookings_course_fill on public.bookings;
create trigger bookings_course_fill before insert or update of course_id, year_level, course_level, qualification on public.bookings
  for each row execute function public.hsc_fill_course();

alter table public.hsc_subject_areas enable row level security;
alter table public.hsc_courses enable row level security;
alter table public.hsc_course_years enable row level security;
alter table public.course_offerings enable row level security;
alter table public.tutor_courses enable row level security;
alter table public.student_courses enable row level security;

-- ===== supabase/migrations/20261019000003_archive_requests.sql =====
-- Lets admins and the owner archive a request. An archived request keeps its details,
-- decisions and history. It leaves the normal lists and shows under "Archived requests",
-- where it can be restored. Archiving never changes the decision or the status.
alter table public.requests
  add column if not exists archived_at timestamptz,
  add column if not exists archived_by uuid references public.app_users (id);

alter table public.request_events drop constraint if exists request_events_event_type_check;
alter table public.request_events add constraint request_events_event_type_check check (event_type in (
  'created', 'reevaluated', 'sent_to_owner', 'owner_approved', 'owner_declined',
  'owner_requested_info', 'admin_replied', 'admin_recorded', 'closed',
  'removed_from_list', 'restored_to_list', 'archived', 'unarchived'
));

-- ===== supabase/migrations/20261019000004_request_classes.sql =====
-- Gives each request its own class: the exact HSC course and year it is about. Two
-- requests on the same booking can be about different classes, so the class is saved on
-- the request. The same catalogue trigger as bookings fills in the subject area and the
-- class code (for example MTH1011), and rejects a course that doesn't run in that year.
alter table public.requests
  add column if not exists course_id text,
  add column if not exists year_level smallint,
  add column if not exists area_id text,
  add column if not exists category_code text,
  add column if not exists course_level text not null default '',
  add column if not exists qualification text not null default '',
  add column if not exists class_set_by uuid references public.app_users (id),
  add column if not exists class_set_at timestamptz;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'requests_course_year_fk') then
    alter table public.requests add constraint requests_course_year_fk
      foreign key (course_id, year_level) references public.hsc_course_years (course_id, year_level);
  end if;
end $$;

drop trigger if exists requests_course_fill on public.requests;
create trigger requests_course_fill before insert or update of course_id, year_level, course_level, qualification on public.requests
  for each row execute function public.hsc_fill_course();

alter table public.request_events drop constraint if exists request_events_event_type_check;
alter table public.request_events add constraint request_events_event_type_check check (event_type in (
  'created', 'reevaluated', 'sent_to_owner', 'owner_approved', 'owner_declined',
  'owner_requested_info', 'admin_replied', 'admin_recorded', 'closed',
  'removed_from_list', 'restored_to_list', 'archived', 'unarchived', 'class_changed'
));

-- Older requests: copy the class from their booking, but only when the booking is
-- linked to exactly one course. Requests whose class can't be worked out stay empty,
-- and someone can choose the class on the request's page.
update public.requests r
   set course_id = b.course_id, year_level = b.year_level, course_level = b.course_level, qualification = b.qualification
  from public.bookings b
 where r.course_id is null
   and b.course_id is not null
   and b.id = coalesce(r.booking_id, case when r.reference_id ~ '^BK-[0-9]+$' then r.reference_id end);

-- ===== supabase/migrations/20261020000001_compass_assistant.sql =====
-- Compass owner assistant: conversation state kept on the server, and one approval
-- process for every business change Compass prepares.
--
-- Compass may read records and prepare unsaved drafts on its own. Anything that saves
-- (a draft, a new request, a workflow step or an owner decision) becomes a proposal
-- first. The person sees the exact preview and confirms it, and only then does
-- execute_agent_proposal make the change, in one transaction with its audit record.

-- Conversation state ---------------------------------------------------------------
-- One row per Compass conversation. The browser only holds the session key; the task
-- Compass is working on and the request in focus live here, tied to the signed-in user.
create table if not exists public.agent_sessions (
  session_key uuid primary key,
  user_id uuid not null references public.app_users (id) on delete cascade,
  state jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
create index if not exists agent_sessions_user_idx on public.agent_sessions (user_id, updated_at desc);

-- Proposals ------------------------------------------------------------------------
create table if not exists public.agent_proposals (
  id uuid primary key default gen_random_uuid(),
  created_by uuid not null references public.app_users (id),
  created_role text not null check (created_role in ('admin', 'owner')),
  session_key uuid,
  action_type text not null check (action_type in (
    'request.create', 'request.send_to_owner', 'request.approve', 'request.decline',
    'request.request_info', 'request.record_outcome', 'draft.save'
  )),
  -- 'request' targets an existing request; 'new_request' is a request not yet saved.
  target_type text not null check (target_type in ('request', 'new_request')),
  target_id uuid,
  inputs jsonb not null,
  input_hash text not null check (char_length(input_hash) = 64),
  -- The record and policy versions the preview was built from.
  preconditions jsonb not null,
  -- Exactly what the person was shown: current and proposed values, warnings, policy references.
  preview jsonb not null,
  -- 'staff' means an admin or the owner may confirm. 'owner' means only the owner.
  required_role text not null check (required_role in ('staff', 'owner')),
  status text not null default 'pending' check (status in (
    'pending', 'succeeded', 'failed', 'expired', 'cancelled', 'superseded', 'stale'
  )),
  replaces uuid references public.agent_proposals (id),
  expires_at timestamptz not null,
  confirmed_by uuid references public.app_users (id),
  confirmed_at timestamptz,
  result jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((target_type = 'request') = (target_id is not null))
);
create index if not exists agent_proposals_creator_idx on public.agent_proposals (created_by, created_at desc);
create index if not exists agent_proposals_target_idx on public.agent_proposals (target_id);

-- A proposal's action, target, inputs and preview can never be changed. Editing makes
-- a new proposal and marks the old one superseded.
create or replace function public.protect_agent_proposals() returns trigger
language plpgsql as $$
begin
  if new.action_type is distinct from old.action_type
     or new.target_type is distinct from old.target_type
     or new.target_id is distinct from old.target_id
     or new.inputs is distinct from old.inputs
     or new.input_hash is distinct from old.input_hash
     or new.preconditions is distinct from old.preconditions
     or new.preview is distinct from old.preview
     or new.required_role is distinct from old.required_role
     or new.created_by is distinct from old.created_by then
    raise exception 'invalid_input: a proposal cannot be changed after it is prepared';
  end if;
  if old.status <> 'pending' and new.status is distinct from old.status then
    raise exception 'invalid_transition: this proposal is already %', old.status;
  end if;
  return new;
end $$;

drop trigger if exists agent_proposals_protect on public.agent_proposals;
create trigger agent_proposals_protect before update on public.agent_proposals
  for each row execute function public.protect_agent_proposals();

-- Run a confirmed proposal. Called only by the server, after it has re-run the business
-- rules. This function checks again, under a row lock:
--   * the person confirming prepared it, and still has the required role
--   * it is still pending and has not expired
--   * the request has not changed since the preview (status, decision, last update,
--     archived or removed, and the draft being replaced)
-- Then it makes the change through the existing workflow functions and writes the audit
-- record, all in this one transaction. A second call returns the first result.
create or replace function public.execute_agent_proposal(p_id uuid, p_actor uuid, p_payload jsonb)
returns jsonb
language plpgsql as $$
declare
  v_p public.agent_proposals;
  v_role text;
  v_pre jsonb;
  v_row jsonb;
  v_changed text[] := '{}';
  v_result jsonb;
  v_draft_at timestamptz;
  v_kind text;
begin
  select * into v_p from public.agent_proposals where id = p_id for update;
  if not found then raise exception 'not_found: proposal not found'; end if;
  if v_p.created_by <> p_actor then
    raise exception 'forbidden: only the person who prepared this can confirm it';
  end if;
  if v_p.status = 'succeeded' then
    return jsonb_build_object('ok', true, 'duplicate', true, 'result', v_p.result);
  end if;
  if v_p.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', v_p.status, 'result', v_p.result);
  end if;
  if v_p.expires_at <= now() then
    update public.agent_proposals set status = 'expired', updated_at = now() where id = p_id;
    return jsonb_build_object('ok', false, 'code', 'expired');
  end if;

  v_role := public.actor_role(p_actor);
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if v_p.required_role = 'owner' and v_role <> 'owner' then
    raise exception 'forbidden: only the owner can confirm this decision';
  end if;

  v_pre := v_p.preconditions;
  if v_p.target_type = 'request' then
    select to_jsonb(r) into v_row from public.requests r where r.id = v_p.target_id for update;
    if v_row is null then raise exception 'not_found: request not found'; end if;
    if v_row->>'status' is distinct from v_pre->>'status' then v_changed := array_append(v_changed, 'status'); end if;
    if v_row->>'current_decision_id' is distinct from v_pre->>'currentDecisionId' then v_changed := array_append(v_changed, 'decision'); end if;
    if (v_row->>'updated_at')::timestamptz is distinct from (v_pre->>'updatedAt')::timestamptz then v_changed := array_append(v_changed, 'updated'); end if;
    if (v_row->>'archived_at' is null) <> (v_pre->>'archivedAt' is null) then v_changed := array_append(v_changed, 'archived'); end if;
    if (v_row->>'hidden_at' is null) <> (v_pre->>'hiddenAt' is null) then v_changed := array_append(v_changed, 'removed'); end if;
    if v_p.action_type = 'draft.save' then
      v_kind := v_p.inputs->>'kind';
      select updated_at into v_draft_at from public.drafts where request_id = v_p.target_id and kind = v_kind for update;
      if v_draft_at is distinct from (v_pre->>'draftUpdatedAt')::timestamptz then v_changed := array_append(v_changed, 'draft'); end if;
    end if;
  elsif v_p.action_type = 'request.create' then
    -- The server re-ran the engine just now. Its inputs and outcome must match the preview.
    if p_payload->'request'->'confirmed_facts' is distinct from v_p.inputs->'facts' then
      raise exception 'invalid_input: the facts do not match the confirmed preview';
    end if;
    if p_payload->'request'->>'decision' is distinct from v_pre->'decision'->>'colour'
       or p_payload->'request'->>'matched_rule_id' is distinct from v_pre->'decision'->>'matchedRuleId' then
      v_changed := array_append(v_changed, 'decision');
    end if;
  end if;

  if cardinality(v_changed) > 0 then
    update public.agent_proposals
       set status = 'stale', result = jsonb_build_object('changed', to_jsonb(v_changed)), updated_at = now()
     where id = p_id;
    return jsonb_build_object('ok', false, 'code', 'stale', 'changed', to_jsonb(v_changed));
  end if;

  begin
    case v_p.action_type
      when 'request.create' then
        v_result := public.create_request(
          p_payload || jsonb_build_object('idempotency_key', p_id, 'actor_id', p_actor, 'intake_method', 'ai_intake')
        );
      when 'request.send_to_owner' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'send_to_owner', v_p.inputs->>'note');
      when 'request.approve' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'approve', v_p.inputs->>'note');
      when 'request.decline' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'decline', v_p.inputs->>'note');
      when 'request.request_info' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'request_info', v_p.inputs->>'note');
      when 'request.record_outcome' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'record_and_close', v_p.inputs->>'note');
      when 'draft.save' then
        insert into public.drafts (request_id, kind, body, generated_by, updated_by, updated_at)
        values (v_p.target_id, v_kind, v_p.inputs->>'body', coalesce(v_p.inputs->>'generatedBy', 'edited'), p_actor, now())
        on conflict (request_id, kind) do update
          set body = excluded.body, generated_by = excluded.generated_by, updated_by = excluded.updated_by, updated_at = now();
        v_result := jsonb_build_object('id', v_p.target_id, 'kind', v_kind, 'saved', true);
    end case;
  exception when others then
    -- Nothing from the business change is kept. The proposal records why it failed.
    update public.agent_proposals
       set status = 'failed', result = jsonb_build_object('error', sqlerrm), confirmed_by = p_actor, confirmed_at = now(), updated_at = now()
     where id = p_id;
    return jsonb_build_object('ok', false, 'code', 'failed', 'error', sqlerrm);
  end;

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'agent.' || v_p.action_type, 'agent_proposal', p_id::text,
          jsonb_build_object('target', coalesce(v_p.target_id::text, v_result->>'id'), 'input_hash', v_p.input_hash,
                             'prepared_by_role', v_p.created_role, 'result', v_result));

  update public.agent_proposals
     set status = 'succeeded', confirmed_by = p_actor, confirmed_at = now(), result = v_result, updated_at = now()
   where id = p_id;

  return jsonb_build_object('ok', true, 'duplicate', false, 'result', v_result);
end $$;

-- New activity kinds for Compass's reads and proposals.
alter table public.ai_activity drop constraint if exists ai_activity_event_type_check;
alter table public.ai_activity add constraint ai_activity_event_type_check check (event_type in (
  'details_extracted', 'clarification_needed', 'booking_retrieved', 'payment_found',
  'availability_checked', 'policy_retrieved', 'missing_information', 'confirmation_required',
  'decision_completed', 'draft_prepared', 'owner_review_created', 'rule_proposed',
  'suggestion_prepared', 'ai_unavailable',
  'records_retrieved', 'briefing_prepared', 'proposal_prepared', 'proposal_confirmed',
  'proposal_cancelled', 'sensitive_case_routed'
));

alter table public.agent_sessions enable row level security;
alter table public.agent_proposals enable row level security;

revoke all on function public.execute_agent_proposal(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.execute_agent_proposal(uuid, uuid, jsonb) to service_role;

-- ===== supabase/migrations/20261020000002_owner_review.sql =====
-- Owner review: the owner reviews requests directly instead of being asked to send them
-- to themselves, and nothing goes to the owner while required details are missing.
--
-- * requests.owner_review_started_at / _by record when the owner pressed Start Review.
--   Opening a request never changes it; only the explicit Start Review does.
-- * start_owner_review records that once (repeat clicks change nothing).
-- * add_owner_handling_note records the owner's handling notes and next steps on a red or
--   welfare request as an event, without changing its status.
-- * transition_request is replaced with role and missing-detail checks:
--     - send_to_owner is refused for the owner and while required details are missing;
--     - the owner can approve, decline or ask for information on review_required,
--       more_info_requested, awaiting_owner, and needs_clarification once details are
--       complete, without an admin sending it first;
--     - approve is refused while the latest rule check has missing details;
--     - an admin can never make an owner decision.
-- Safe to run more than once.

alter table public.requests
  add column if not exists owner_review_started_at timestamptz,
  add column if not exists owner_review_started_by uuid references public.app_users (id);

alter table public.request_events drop constraint if exists request_events_event_type_check;
alter table public.request_events add constraint request_events_event_type_check check (event_type in (
  'created', 'reevaluated', 'sent_to_owner', 'owner_approved', 'owner_declined',
  'owner_requested_info', 'admin_replied', 'admin_recorded', 'closed',
  'removed_from_list', 'restored_to_list', 'archived', 'unarchived', 'class_changed',
  'owner_review_started', 'owner_handling_note'
));

-- How many required details the latest rule check says are missing. "policy" and
-- "request_type" are not details anyone can fill in, so they don't count.
create or replace function public.request_missing_count(p_request_id uuid) returns integer
language sql stable as $$
  select coalesce((
    select count(*)::integer
    from public.requests r
    join public.decisions d on d.id = r.current_decision_id
    cross join lateral jsonb_array_elements(coalesce(d.result->'missing', '[]'::jsonb)) m
    where r.id = p_request_id and coalesce(m->>'fact', '') not in ('policy', 'request_type')
  ), 0)
$$;

create or replace function public.transition_request(
  p_request_id uuid, p_actor uuid, p_action text, p_note text
) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_from text[];
  v_to text;
  v_event text;
  v_owner_only boolean := false;
  v_old_status text;
  v_missing integer;
  v_owner_from constant text[] := array['review_required', 'needs_clarification', 'more_info_requested', 'awaiting_owner'];
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if coalesce(btrim(p_note), '') = '' then raise exception 'reason_required: a note or reason is required'; end if;
  if char_length(p_note) > 4000 then raise exception 'invalid_input: note is too long'; end if;

  case p_action
    when 'send_to_owner' then
      v_from := array['review_required', 'needs_clarification', 'more_info_requested']; v_to := 'awaiting_owner'; v_event := 'sent_to_owner';
    when 'approve' then
      v_from := v_owner_from; v_to := 'approved'; v_event := 'owner_approved'; v_owner_only := true;
    when 'decline' then
      v_from := v_owner_from; v_to := 'declined'; v_event := 'owner_declined'; v_owner_only := true;
    when 'request_info' then
      v_from := v_owner_from; v_to := 'more_info_requested'; v_event := 'owner_requested_info'; v_owner_only := true;
    when 'record_and_close' then
      v_from := array['ready', 'approved', 'declined']; v_to := 'closed'; v_event := 'closed';
    else
      raise exception 'invalid_input: unknown action %', p_action;
  end case;

  if v_owner_only and v_role <> 'owner' then
    raise exception 'forbidden: only the owner can do this';
  end if;
  if p_action = 'send_to_owner' and v_role = 'owner' then
    raise exception 'forbidden: the owner reviews requests directly and does not send them to themselves';
  end if;

  select status into v_old_status from public.requests where id = p_request_id for update;
  if not found then raise exception 'not_found'; end if;

  v_missing := public.request_missing_count(p_request_id);
  if v_missing > 0 and v_old_status = any (array['review_required', 'needs_clarification', 'more_info_requested', 'awaiting_owner']) then
    if p_action = 'send_to_owner' then
      raise exception 'missing_details: complete the missing details before sending this to the owner';
    end if;
    if p_action = 'approve' then
      raise exception 'missing_details: complete the missing details before approving';
    end if;
    if v_owner_only and v_old_status = 'needs_clarification' then
      raise exception 'missing_details: complete the missing details before the owner reviews this';
    end if;
  end if;

  -- The status check and the update happen together, so a second click finds the
  -- status already changed and does nothing.
  update public.requests set status = v_to, updated_at = now()
  where id = p_request_id and status = any (v_from);
  if not found then
    raise exception 'invalid_transition: cannot % a request that is %', p_action, v_old_status;
  end if;

  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (p_request_id, v_event, p_actor, v_role, v_old_status, v_to, p_note);

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'request.' || p_action, 'request', p_request_id::text,
          jsonb_build_object('from', v_old_status, 'to', v_to));

  return jsonb_build_object('id', p_request_id, 'status', v_to);
end $$;

-- The owner starts reviewing a request. Records who and when, once. It changes no status,
-- and it leaves updated_at alone so prepared Compass proposals stay valid.
create or replace function public.start_owner_review(p_request_id uuid, p_actor uuid) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_row record;
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if v_role <> 'owner' then raise exception 'forbidden: only the owner can start a review'; end if;

  select id, status, owner_review_started_at, owner_review_started_by into v_row
  from public.requests where id = p_request_id for update;
  if not found then raise exception 'not_found'; end if;

  if v_row.owner_review_started_at is not null then
    return jsonb_build_object('id', p_request_id, 'status', v_row.status, 'started_at', v_row.owner_review_started_at,
                              'started_by', v_row.owner_review_started_by, 'already', true);
  end if;
  if v_row.status <> all (array['review_required', 'needs_clarification', 'more_info_requested', 'awaiting_owner']) then
    raise exception 'invalid_transition: a request that is % cannot be reviewed', v_row.status;
  end if;
  if v_row.status = 'needs_clarification' and public.request_missing_count(p_request_id) > 0 then
    raise exception 'missing_details: complete the missing details before the owner reviews this';
  end if;

  update public.requests set owner_review_started_at = now(), owner_review_started_by = p_actor
  where id = p_request_id;

  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (p_request_id, 'owner_review_started', p_actor, v_role, v_row.status, v_row.status, 'Owner started the review.');

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'request.start_review', 'request', p_request_id::text, jsonb_build_object('status', v_row.status));

  return jsonb_build_object('id', p_request_id, 'status', v_row.status, 'started_at', now(), 'started_by', p_actor, 'already', false);
end $$;

-- The owner records how they are handling a request, with next steps. No status change.
create or replace function public.add_owner_handling_note(p_request_id uuid, p_actor uuid, p_note text) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_status text;
  v_event uuid;
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if v_role <> 'owner' then raise exception 'forbidden: only the owner can record handling notes'; end if;
  if coalesce(btrim(p_note), '') = '' then raise exception 'reason_required: a note is required'; end if;
  if char_length(p_note) > 4000 then raise exception 'invalid_input: note is too long'; end if;

  select status into v_status from public.requests where id = p_request_id for update;
  if not found then raise exception 'not_found'; end if;
  if v_status <> all (array['review_required', 'needs_clarification', 'more_info_requested', 'awaiting_owner']) then
    raise exception 'invalid_transition: handling notes can only be added while the owner is reviewing';
  end if;

  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (p_request_id, 'owner_handling_note', p_actor, v_role, v_status, v_status, btrim(p_note))
  returning id into v_event;

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'request.handling_note', 'request', p_request_id::text, jsonb_build_object('status', v_status));

  return jsonb_build_object('id', p_request_id, 'status', v_status, 'event_id', v_event);
end $$;

-- Only the server (service role) may call these functions.
revoke all on function public.request_missing_count(uuid) from public, anon, authenticated;
revoke all on function public.transition_request(uuid, uuid, text, text) from public, anon, authenticated;
revoke all on function public.start_owner_review(uuid, uuid) from public, anon, authenticated;
revoke all on function public.add_owner_handling_note(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.request_missing_count(uuid) to service_role;
grant execute on function public.transition_request(uuid, uuid, text, text) to service_role;
grant execute on function public.start_owner_review(uuid, uuid) to service_role;
grant execute on function public.add_owner_handling_note(uuid, uuid, text) to service_role;

-- ===== supabase/migrations/20261021000001_compass_workflows.sql =====
-- Compass workflows: Lesson Change, Payment Extension and Tutor Absence.
--
-- Each workflow ends in a real, checked change to Tutor Compass's own records, never a
-- message to a family or tutor and never a payment:
--   * booking.reschedule      moves one scheduled lesson to a free slot (same tutor, or an
--                             owner-approved cover tutor) and closes the linked request.
--   * invoice.extend_due_date moves an unpaid invoice's due date, replaces its reminder
--                             schedule (recorded only: nothing is sent) and closes the
--                             linked request.
--   * tutor.record_absence    records when a tutor is unavailable, so their slots are no
--                             longer offered.
-- The first two need a saved request that the owner's rules made Ready for Admin, or that
-- the owner approved. Every change still goes through agent_proposals and
-- execute_agent_proposal: the person confirms the exact preview, and the database checks
-- role, status and the records again under a lock before anything changes.
-- Safe to run more than once. It adds tables and columns and changes no existing data.

-- Scheduled lessons ----------------------------------------------------------------
-- One row per lesson on a booking. A scheduled lesson holds its tutor's slot.
create table if not exists public.lessons (
  id text primary key check (id ~ '^LSN-[0-9]{3,8}$'),
  booking_id text not null references public.bookings (id),
  tutor_id text not null references public.tutors (id),
  slot_id text references public.tutor_availability (id),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status text not null default 'scheduled' check (status in ('scheduled', 'completed', 'cancelled')),
  data_label text not null default 'fictional_demo'
    check (data_label in ('live_connected', 'imported', 'fictional_demo')),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.app_users (id),
  check (ends_at > starts_at)
);
create index if not exists lessons_booking_idx on public.lessons (booking_id, starts_at);
create index if not exists lessons_tutor_idx on public.lessons (tutor_id, starts_at);
-- A slot can hold only one scheduled lesson.
create unique index if not exists lessons_one_per_slot on public.lessons (slot_id) where slot_id is not null and status = 'scheduled';

-- Invoices ---------------------------------------------------------------------------
-- When the invoice last changed in Tutor Compass, and the due date it started with.
alter table public.payments
  add column if not exists updated_at timestamptz not null default now(),
  add column if not exists original_due_date date;

-- Reminder schedule for an unpaid invoice. Tutor Compass records the schedule only. It is
-- not connected to email or SMS, so nothing here is ever sent.
create table if not exists public.payment_reminders (
  id uuid primary key default gen_random_uuid(),
  payment_id text not null references public.payments (id),
  remind_on date not null,
  kind text not null check (kind in ('before_due', 'due_today', 'overdue')),
  status text not null default 'scheduled' check (status in ('scheduled', 'cancelled')),
  delivery text not null default 'not_connected' check (delivery in ('not_connected')),
  created_by uuid references public.app_users (id),
  created_at timestamptz not null default now(),
  cancelled_at timestamptz
);
create index if not exists payment_reminders_payment_idx on public.payment_reminders (payment_id, remind_on);

-- Tutor absences ----------------------------------------------------------------------
create table if not exists public.tutor_absences (
  id uuid primary key default gen_random_uuid(),
  tutor_id text not null references public.tutors (id),
  starts_on date not null,
  ends_on date not null,
  note text not null default '' check (char_length(note) <= 500),
  status text not null default 'recorded' check (status in ('recorded', 'cancelled')),
  created_by uuid references public.app_users (id),
  created_at timestamptz not null default now(),
  check (ends_on >= starts_on),
  check (ends_on - starts_on <= 60)
);
create index if not exists tutor_absences_tutor_idx on public.tutor_absences (tutor_id, starts_on);

-- Is this tutor recorded as away at this moment (Sydney date)?
create or replace function public.tutor_is_absent(p_tutor text, p_at timestamptz) returns boolean
language sql stable as $$
  select exists (
    select 1 from public.tutor_absences a
    where a.tutor_id = p_tutor and a.status = 'recorded'
      and (p_at at time zone 'Australia/Sydney')::date between a.starts_on and a.ends_on
  )
$$;

-- Compass workflow runs ----------------------------------------------------------------
-- Where a Lesson Change, Payment Extension or Tutor Absence workflow is up to, so it can
-- be continued from any chat and listed under What Needs My Attention. The records and
-- the request stay the source of truth; this only remembers the person's choices.
create table if not exists public.agent_workflows (
  id uuid primary key default gen_random_uuid(),
  workflow text not null check (workflow in ('lesson_change', 'payment_extension', 'tutor_absence')),
  created_by uuid not null references public.app_users (id) on delete cascade,
  session_key uuid,
  status text not null default 'active' check (status in ('active', 'waiting', 'completed', 'cancelled')),
  stage text not null default 'start' check (char_length(stage) <= 60),
  summary text not null default '' check (char_length(summary) <= 300),
  state jsonb not null default '{}'::jsonb,
  request_id uuid references public.requests (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists agent_workflows_user_idx on public.agent_workflows (created_by, status, updated_at desc);

-- Proposals: the three new actions -------------------------------------------------------
alter table public.agent_proposals drop constraint if exists agent_proposals_action_type_check;
alter table public.agent_proposals add constraint agent_proposals_action_type_check check (action_type in (
  'request.create', 'request.send_to_owner', 'request.approve', 'request.decline',
  'request.request_info', 'request.record_outcome', 'draft.save',
  'booking.reschedule', 'invoice.extend_due_date', 'tutor.record_absence'
));
alter table public.agent_proposals drop constraint if exists agent_proposals_target_type_check;
alter table public.agent_proposals add constraint agent_proposals_target_type_check
  check (target_type in ('request', 'new_request', 'tutor'));

-- Move a lesson for a request the rules or the owner have cleared. Called only from
-- execute_agent_proposal, inside its transaction.
create or replace function public.apply_lesson_change(p_request_id uuid, p_actor uuid, p_inputs jsonb) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_req record;
  v_lesson public.lessons;
  v_slot public.tutor_availability;
  v_booking public.bookings;
  v_old_tutor text;
  v_new_tutor text;
  v_fmt constant text := 'Dy FMDD Mon FMHH12:MI am';
  v_note text;
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  select id, request_type, status, booking_id, confirmed_facts into v_req from public.requests where id = p_request_id for update;
  if not found then raise exception 'not_found: request not found'; end if;
  if v_req.request_type <> 'lesson_change' then raise exception 'invalid_input: this request is not a lesson change'; end if;
  if v_req.status not in ('ready', 'approved') then
    raise exception 'invalid_transition: the lesson can only be moved once the rules allow it or the owner approves (the request is %)', v_req.status;
  end if;
  if v_req.confirmed_facts->>'proposedSlotId' is distinct from p_inputs->>'newSlotId' then
    raise exception 'invalid_input: the new time is not the one on the request';
  end if;

  select * into v_lesson from public.lessons where id = p_inputs->>'lessonId' for update;
  if not found then raise exception 'not_found: lesson not found'; end if;
  if v_lesson.booking_id is distinct from v_req.booking_id then raise exception 'invalid_input: the lesson is not on this booking'; end if;
  if v_lesson.status <> 'scheduled' then raise exception 'invalid_transition: the lesson is %', v_lesson.status; end if;

  select * into v_slot from public.tutor_availability where id = p_inputs->>'newSlotId' for update;
  if not found then raise exception 'not_found: time slot not found'; end if;
  if v_slot.status <> 'free' then raise exception 'stale_update: that time is no longer free'; end if;
  if v_slot.starts_at <= now() then raise exception 'invalid_input: that time has already passed'; end if;
  if public.tutor_is_absent(v_slot.tutor_id, v_slot.starts_at) then raise exception 'invalid_input: the tutor is recorded as away at that time'; end if;

  select * into v_booking from public.bookings where id = v_lesson.booking_id;
  -- A different tutor is a cover arrangement. The rules never make that routine, so only an owner approval allows it.
  if v_slot.tutor_id <> v_booking.tutor_id and v_req.status <> 'approved' then
    raise exception 'forbidden: a different tutor needs the owner''s approval';
  end if;
  if exists (
    select 1 from public.lessons l join public.bookings b on b.id = l.booking_id
    where b.family_id = v_booking.family_id and l.status = 'scheduled' and l.id <> v_lesson.id
      and l.starts_at < v_slot.ends_at and l.ends_at > v_slot.starts_at
  ) then
    raise exception 'invalid_input: the family already has a lesson at that time';
  end if;

  v_old_tutor := (select name from public.tutors where id = v_lesson.tutor_id);
  v_new_tutor := (select name from public.tutors where id = v_slot.tutor_id);

  update public.tutor_availability set status = 'booked' where id = v_slot.id and status = 'free';
  if not found then raise exception 'stale_update: that time is no longer free'; end if;
  if v_lesson.slot_id is not null then
    update public.tutor_availability set status = 'free' where id = v_lesson.slot_id;
  end if;
  update public.lessons
     set tutor_id = v_slot.tutor_id, slot_id = v_slot.id, starts_at = v_slot.starts_at, ends_at = v_slot.ends_at,
         updated_at = now(), updated_by = p_actor
   where id = v_lesson.id;

  v_note := format('Lesson %s moved in Tutor Compass from %s with %s to %s with %s.%s No message was sent to the family or tutor.',
    v_lesson.id,
    to_char(v_lesson.starts_at at time zone 'Australia/Sydney', v_fmt), v_old_tutor,
    to_char(v_slot.starts_at at time zone 'Australia/Sydney', v_fmt), v_new_tutor,
    case when coalesce(p_inputs->>'agreement', '') <> '' then ' ' || (p_inputs->>'agreement') else '' end);

  update public.requests set status = 'closed', updated_at = now() where id = p_request_id;
  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (p_request_id, 'closed', p_actor, v_role, v_req.status, 'closed', left(v_note, 4000));
  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'lesson.reschedule', 'lesson', v_lesson.id,
          jsonb_build_object('request', p_request_id, 'from_slot', v_lesson.slot_id, 'to_slot', v_slot.id,
                             'from_tutor', v_lesson.tutor_id, 'to_tutor', v_slot.tutor_id,
                             'from', v_lesson.starts_at, 'to', v_slot.starts_at));

  return jsonb_build_object('id', p_request_id, 'status', 'closed', 'lessonId', v_lesson.id,
    'before', jsonb_build_object('slotId', v_lesson.slot_id, 'tutorId', v_lesson.tutor_id, 'startsAt', v_lesson.starts_at),
    'after', jsonb_build_object('slotId', v_slot.id, 'tutorId', v_slot.tutor_id, 'startsAt', v_slot.starts_at));
end $$;

-- Give an unpaid invoice more time and replace its reminder schedule.
create or replace function public.apply_invoice_extension(p_request_id uuid, p_actor uuid, p_inputs jsonb) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_req record;
  v_pay public.payments;
  v_days integer := (p_inputs->>'extensionDays')::integer;
  v_new date := (p_inputs->>'newDueDate')::date;
  v_status text;
  v_rem jsonb;
  v_count integer := 0;
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  select id, request_type, status, booking_id, confirmed_facts into v_req from public.requests where id = p_request_id for update;
  if not found then raise exception 'not_found: request not found'; end if;
  if v_req.request_type <> 'payment_extension' then raise exception 'invalid_input: this request is not a payment extension'; end if;
  if v_req.status not in ('ready', 'approved') then
    raise exception 'invalid_transition: the due date can only change once the rules allow it or the owner approves (the request is %)', v_req.status;
  end if;
  if (v_req.confirmed_facts->>'extensionDays')::integer is distinct from v_days then
    raise exception 'invalid_input: the extra days are not the ones on the request';
  end if;

  select * into v_pay from public.payments where id = p_inputs->>'paymentId' for update;
  if not found then raise exception 'not_found: invoice not found'; end if;
  if v_pay.booking_id is distinct from v_req.booking_id then raise exception 'invalid_input: the invoice is not on this booking'; end if;
  if v_pay.status not in ('pending', 'overdue') then raise exception 'invalid_transition: the invoice is %', v_pay.status; end if;
  if v_pay.due_date is null then raise exception 'invalid_input: the invoice has no due date'; end if;
  if v_new is distinct from v_pay.due_date + v_days then raise exception 'invalid_input: the new due date does not match the extra days'; end if;

  v_status := case when v_new >= current_date then 'pending' else v_pay.status end;
  update public.payments
     set original_due_date = coalesce(original_due_date, due_date), due_date = v_new, status = v_status, updated_at = now()
   where id = v_pay.id;

  update public.payment_reminders set status = 'cancelled', cancelled_at = now()
   where payment_id = v_pay.id and status = 'scheduled';
  for v_rem in select * from jsonb_array_elements(coalesce(p_inputs->'reminders', '[]'::jsonb)) loop
    if (v_rem->>'date')::date not between v_new - 7 and v_new + 14 then
      raise exception 'invalid_input: a reminder date is too far from the new due date';
    end if;
    insert into public.payment_reminders (payment_id, remind_on, kind, created_by)
    values (v_pay.id, (v_rem->>'date')::date, v_rem->>'kind', p_actor);
    v_count := v_count + 1;
  end loop;

  update public.requests set status = 'closed', updated_at = now() where id = p_request_id;
  insert into public.request_events (request_id, event_type, actor_id, actor_role, from_status, to_status, note)
  values (p_request_id, 'closed', p_actor, v_role, v_req.status, 'closed',
          format('Invoice %s (%s) due date moved in Tutor Compass from %s to %s, %s extra days. %s reminders scheduled in Tutor Compass only. Nothing was sent to the family.',
                 v_pay.invoice_ref, v_pay.id, to_char(v_pay.due_date, 'FMDD Mon YYYY'), to_char(v_new, 'FMDD Mon YYYY'), v_days, v_count));
  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'invoice.extend_due_date', 'payment', v_pay.id,
          jsonb_build_object('request', p_request_id, 'from', v_pay.due_date, 'to', v_new, 'days', v_days, 'reminders', v_count));

  return jsonb_build_object('id', p_request_id, 'status', 'closed', 'paymentId', v_pay.id,
    'before', jsonb_build_object('dueDate', v_pay.due_date, 'status', v_pay.status),
    'after', jsonb_build_object('dueDate', v_new, 'status', v_status), 'reminders', v_count);
end $$;

-- Record that a tutor is unavailable. It changes no lesson by itself.
create or replace function public.record_tutor_absence(p_actor uuid, p_inputs jsonb) returns jsonb
language plpgsql as $$
declare
  v_role text := public.actor_role(p_actor);
  v_start date := (p_inputs->>'startsOn')::date;
  v_end date := (p_inputs->>'endsOn')::date;
  v_id uuid;
begin
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if not exists (select 1 from public.tutors where id = p_inputs->>'tutorId') then raise exception 'not_found: tutor not found'; end if;
  if v_start is null or v_end is null or v_end < v_start then raise exception 'invalid_input: check the dates'; end if;
  if v_end - v_start > 60 then raise exception 'invalid_input: record absences of up to 60 days at a time'; end if;
  if exists (select 1 from public.tutor_absences where tutor_id = p_inputs->>'tutorId' and status = 'recorded'
             and starts_on <= v_end and ends_on >= v_start) then
    raise exception 'invalid_input: an absence is already recorded for some of these dates';
  end if;
  insert into public.tutor_absences (tutor_id, starts_on, ends_on, note, created_by)
  values (p_inputs->>'tutorId', v_start, v_end, left(coalesce(p_inputs->>'note', ''), 500), p_actor)
  returning id into v_id;
  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'tutor.record_absence', 'tutor_absence', v_id::text,
          jsonb_build_object('tutor', p_inputs->>'tutorId', 'from', v_start, 'to', v_end));
  return jsonb_build_object('absenceId', v_id, 'tutorId', p_inputs->>'tutorId', 'startsOn', v_start, 'endsOn', v_end);
end $$;

-- execute_agent_proposal, now with the three workflow actions. Everything from the
-- earlier version is kept: creator and role checks, expiry, duplicate confirms and the
-- request checks. The workflow actions also compare the lesson, slot or invoice with the
-- preview under a lock, so a change made since then makes the proposal stale.
create or replace function public.execute_agent_proposal(p_id uuid, p_actor uuid, p_payload jsonb)
returns jsonb
language plpgsql as $$
declare
  v_p public.agent_proposals;
  v_role text;
  v_pre jsonb;
  v_row jsonb;
  v_changed text[] := '{}';
  v_result jsonb;
  v_draft_at timestamptz;
  v_kind text;
  v_lesson public.lessons;
  v_slot public.tutor_availability;
  v_pay public.payments;
  v_overlaps integer;
begin
  select * into v_p from public.agent_proposals where id = p_id for update;
  if not found then raise exception 'not_found: proposal not found'; end if;
  if v_p.created_by <> p_actor then
    raise exception 'forbidden: only the person who prepared this can confirm it';
  end if;
  if v_p.status = 'succeeded' then
    return jsonb_build_object('ok', true, 'duplicate', true, 'result', v_p.result);
  end if;
  if v_p.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', v_p.status, 'result', v_p.result);
  end if;
  if v_p.expires_at <= now() then
    update public.agent_proposals set status = 'expired', updated_at = now() where id = p_id;
    return jsonb_build_object('ok', false, 'code', 'expired');
  end if;

  v_role := public.actor_role(p_actor);
  if v_role is null then raise exception 'forbidden: unknown user'; end if;
  if v_p.required_role = 'owner' and v_role <> 'owner' then
    raise exception 'forbidden: only the owner can confirm this decision';
  end if;

  v_pre := v_p.preconditions;
  if v_p.target_type = 'request' then
    select to_jsonb(r) into v_row from public.requests r where r.id = v_p.target_id for update;
    if v_row is null then raise exception 'not_found: request not found'; end if;
    if v_row->>'status' is distinct from v_pre->>'status' then v_changed := array_append(v_changed, 'status'); end if;
    if v_row->>'current_decision_id' is distinct from v_pre->>'currentDecisionId' then v_changed := array_append(v_changed, 'decision'); end if;
    if (v_row->>'updated_at')::timestamptz is distinct from (v_pre->>'updatedAt')::timestamptz then v_changed := array_append(v_changed, 'updated'); end if;
    if (v_row->>'archived_at' is null) <> (v_pre->>'archivedAt' is null) then v_changed := array_append(v_changed, 'archived'); end if;
    if (v_row->>'hidden_at' is null) <> (v_pre->>'hiddenAt' is null) then v_changed := array_append(v_changed, 'removed'); end if;
    if v_p.action_type = 'draft.save' then
      v_kind := v_p.inputs->>'kind';
      select updated_at into v_draft_at from public.drafts where request_id = v_p.target_id and kind = v_kind for update;
      if v_draft_at is distinct from (v_pre->>'draftUpdatedAt')::timestamptz then v_changed := array_append(v_changed, 'draft'); end if;
    end if;
    if v_p.action_type = 'booking.reschedule' then
      select * into v_lesson from public.lessons where id = v_p.inputs->>'lessonId' for update;
      if not found or v_lesson.status <> 'scheduled' or v_lesson.updated_at is distinct from (v_pre->'workflow'->>'lessonUpdatedAt')::timestamptz then
        v_changed := array_append(v_changed, 'lesson');
      end if;
      select * into v_slot from public.tutor_availability where id = v_p.inputs->>'newSlotId' for update;
      if not found or v_slot.status <> 'free' or v_slot.starts_at is distinct from (v_pre->'workflow'->>'slotStartsAt')::timestamptz then
        v_changed := array_append(v_changed, 'slot');
      end if;
    end if;
    if v_p.action_type = 'invoice.extend_due_date' then
      select * into v_pay from public.payments where id = v_p.inputs->>'paymentId' for update;
      if not found or v_pay.due_date is distinct from (v_pre->'workflow'->>'dueDate')::date
         or v_pay.status is distinct from v_pre->'workflow'->>'paymentStatus'
         or v_pay.updated_at is distinct from (v_pre->'workflow'->>'paymentUpdatedAt')::timestamptz then
        v_changed := array_append(v_changed, 'invoice');
      end if;
    end if;
  elsif v_p.action_type = 'request.create' then
    -- The server re-ran the engine just now. Its inputs and outcome must match the preview.
    if p_payload->'request'->'confirmed_facts' is distinct from v_p.inputs->'facts' then
      raise exception 'invalid_input: the facts do not match the confirmed preview';
    end if;
    if p_payload->'request'->>'decision' is distinct from v_pre->'decision'->>'colour'
       or p_payload->'request'->>'matched_rule_id' is distinct from v_pre->'decision'->>'matchedRuleId' then
      v_changed := array_append(v_changed, 'decision');
    end if;
  elsif v_p.action_type = 'tutor.record_absence' then
    select count(*) into v_overlaps from public.tutor_absences
     where tutor_id = v_p.inputs->>'tutorId' and status = 'recorded'
       and starts_on <= (v_p.inputs->>'endsOn')::date and ends_on >= (v_p.inputs->>'startsOn')::date;
    if v_overlaps <> coalesce((v_pre->'workflow'->>'absenceOverlaps')::integer, 0) then v_changed := array_append(v_changed, 'absence'); end if;
  end if;

  if cardinality(v_changed) > 0 then
    update public.agent_proposals
       set status = 'stale', result = jsonb_build_object('changed', to_jsonb(v_changed)), updated_at = now()
     where id = p_id;
    return jsonb_build_object('ok', false, 'code', 'stale', 'changed', to_jsonb(v_changed));
  end if;

  begin
    case v_p.action_type
      when 'request.create' then
        v_result := public.create_request(
          p_payload || jsonb_build_object('idempotency_key', p_id, 'actor_id', p_actor, 'intake_method', 'ai_intake')
        );
      when 'request.send_to_owner' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'send_to_owner', v_p.inputs->>'note');
      when 'request.approve' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'approve', v_p.inputs->>'note');
      when 'request.decline' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'decline', v_p.inputs->>'note');
      when 'request.request_info' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'request_info', v_p.inputs->>'note');
      when 'request.record_outcome' then
        v_result := public.transition_request(v_p.target_id, p_actor, 'record_and_close', v_p.inputs->>'note');
      when 'draft.save' then
        insert into public.drafts (request_id, kind, body, generated_by, updated_by, updated_at)
        values (v_p.target_id, v_kind, v_p.inputs->>'body', coalesce(v_p.inputs->>'generatedBy', 'edited'), p_actor, now())
        on conflict (request_id, kind) do update
          set body = excluded.body, generated_by = excluded.generated_by, updated_by = excluded.updated_by, updated_at = now();
        v_result := jsonb_build_object('id', v_p.target_id, 'kind', v_kind, 'saved', true);
      when 'booking.reschedule' then
        v_result := public.apply_lesson_change(v_p.target_id, p_actor, v_p.inputs);
      when 'invoice.extend_due_date' then
        v_result := public.apply_invoice_extension(v_p.target_id, p_actor, v_p.inputs);
      when 'tutor.record_absence' then
        v_result := public.record_tutor_absence(p_actor, v_p.inputs);
    end case;
  exception when others then
    -- Nothing from the business change is kept. The proposal records why it failed.
    update public.agent_proposals
       set status = 'failed', result = jsonb_build_object('error', sqlerrm), confirmed_by = p_actor, confirmed_at = now(), updated_at = now()
     where id = p_id;
    return jsonb_build_object('ok', false, 'code', 'failed', 'error', sqlerrm);
  end;

  insert into public.audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (p_actor, v_role, 'agent.' || v_p.action_type, 'agent_proposal', p_id::text,
          jsonb_build_object('target', coalesce(v_p.target_id::text, v_result->>'id', v_result->>'absenceId'), 'input_hash', v_p.input_hash,
                             'prepared_by_role', v_p.created_role, 'result', v_result));

  update public.agent_proposals
     set status = 'succeeded', confirmed_by = p_actor, confirmed_at = now(), result = v_result, updated_at = now()
   where id = p_id;

  return jsonb_build_object('ok', true, 'duplicate', false, 'result', v_result);
end $$;

-- Activity kinds for workflow steps.
alter table public.ai_activity drop constraint if exists ai_activity_event_type_check;
alter table public.ai_activity add constraint ai_activity_event_type_check check (event_type in (
  'details_extracted', 'clarification_needed', 'booking_retrieved', 'payment_found',
  'availability_checked', 'policy_retrieved', 'missing_information', 'confirmation_required',
  'decision_completed', 'draft_prepared', 'owner_review_created', 'rule_proposed',
  'suggestion_prepared', 'ai_unavailable',
  'records_retrieved', 'briefing_prepared', 'proposal_prepared', 'proposal_confirmed',
  'proposal_cancelled', 'sensitive_case_routed',
  'workflow_started', 'workflow_step', 'workflow_completed'
));

alter table public.lessons enable row level security;
alter table public.payment_reminders enable row level security;
alter table public.tutor_absences enable row level security;
alter table public.agent_workflows enable row level security;

-- Only the server (service role) may call these functions.
revoke all on function public.tutor_is_absent(text, timestamptz) from public, anon, authenticated;
revoke all on function public.apply_lesson_change(uuid, uuid, jsonb) from public, anon, authenticated;
revoke all on function public.apply_invoice_extension(uuid, uuid, jsonb) from public, anon, authenticated;
revoke all on function public.record_tutor_absence(uuid, jsonb) from public, anon, authenticated;
revoke all on function public.execute_agent_proposal(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.tutor_is_absent(text, timestamptz) to service_role;
grant execute on function public.apply_lesson_change(uuid, uuid, jsonb) to service_role;
grant execute on function public.apply_invoice_extension(uuid, uuid, jsonb) to service_role;
grant execute on function public.record_tutor_absence(uuid, jsonb) to service_role;
grant execute on function public.execute_agent_proposal(uuid, uuid, jsonb) to service_role;

-- ===== supabase/migrations/20261027000001_demo_reset.sql =====
-- Demo reset: every full page load in demo mode starts from the same original demo data.
--
-- The original demo dataset is defined once, in public.demo_seed() (generated from the
-- seed files by `npm run demo:generate`, see supabase/demo-dataset.sql). The website
-- calls public.reset_demo_data() before it renders a page that was loaded or refreshed in
-- the browser. That throws away every change made to fictional demo records since the
-- last load (bookings, lessons, slots, requests, decisions, owner reviews, rules,
-- absences, payment extensions, reminders, Compass chats and workflow runs) and adds the
-- original records back, with dates worked out again from today in Sydney.
--
-- Only rows labelled 'fictional_demo' are ever removed. Rows labelled 'live_connected' or
-- 'imported' are never touched. Tables that had no label get one here, and as before
-- everything the app creates is labelled 'fictional_demo' unless it says otherwise.
-- Safe to run more than once.

-- Dates for the demo ----------------------------------------------------------------------
-- Today in Sydney. The workflows use the same day (src/lib/workflows/dates.ts).
create or replace function public.demo_today() returns date
language sql stable as $$
  select (now() at time zone 'Australia/Sydney')::date
$$;

-- A demo day, counted from an anchor so each demo lesson always lands on the weekday the
-- class demo script expects, whatever day the demo is run:
--   'today'          today in Sydney
--   'next_monday'    the Monday of next week (a week away when today is a Monday)
--   'next_thursday'  the next Thursday after today, which is what "Thursday" means in Compass
drop function if exists public.demo_day(text, integer);
create or replace function public.demo_day(p_anchor text, p_offset integer, p_today date default public.demo_today()) returns date
language sql stable as $$
  select case p_anchor
    when 'today' then p_today
    when 'next_monday' then p_today + (8 - extract(isodow from p_today)::integer)
    when 'next_thursday' then p_today + coalesce(nullif((4 - extract(dow from p_today)::integer + 7) % 7, 0), 7)
  end + p_offset
$$;

-- A Sydney wall-clock time on a demo day.
create or replace function public.demo_at(p_anchor text, p_offset integer, p_time time) returns timestamptz
language sql stable as $$
  select (public.demo_day(p_anchor, p_offset) + p_time) at time zone 'Australia/Sydney'
$$;

-- Labels on the tables that had none ------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'policy_versions', 'rule_suggestions', 'audit_events', 'ai_activity', 'course_offerings',
    'agent_sessions', 'agent_proposals', 'agent_workflows', 'payment_reminders', 'tutor_absences'
  ] loop
    execute format(
      'alter table public.%I add column if not exists data_label text not null default %L check (data_label in (%L, %L, %L))',
      t, 'fictional_demo', 'live_connected', 'imported', 'fictional_demo');
  end loop;
end $$;

-- Placeholder until supabase/demo-dataset.sql replaces it with the real dataset.
do $$
begin
  if to_regprocedure('public.demo_seed()') is null then
    execute $f$create function public.demo_seed() returns void language plpgsql as $b$
      begin raise exception 'demo_seed_missing: run supabase/demo-dataset.sql'; end $b$
    $f$;
  end if;
end $$;

-- The reset -------------------------------------------------------------------------------
-- Everything happens in one transaction, so a page never sees half-reset data: readers see
-- the old records until the new ones are committed. A lock makes two resets at the same
-- moment run one after the other.
create or replace function public.reset_demo_data() returns jsonb
language plpgsql as $$
declare
  v_kept jsonb;
begin
  perform pg_advisory_xact_lock(hashtext('tutor_compass_demo_reset'));

  -- A real record that relies on a demo rule would lose it, so stop and change nothing.
  if exists (select 1 from public.requests r join public.policy_versions p on p.id = r.policy_version_id
             where r.data_label <> 'fictional_demo' and p.data_label = 'fictional_demo')
     or exists (select 1 from public.decisions d join public.policy_versions p on p.id = d.policy_version_id
                join public.requests r on r.id = d.request_id
                where r.data_label <> 'fictional_demo' and p.data_label = 'fictional_demo') then
    raise exception 'demo_reset_blocked: a request that is not demo data uses a demo rule version, so the demo was not reset';
  end if;

  -- Children first. Decisions, evidence, events, drafts and AI activity for a request go
  -- with the request; tutor and student courses go with their tutor or family.
  delete from public.agent_proposals where data_label = 'fictional_demo';
  delete from public.agent_workflows where data_label = 'fictional_demo';
  delete from public.agent_sessions where data_label = 'fictional_demo';
  delete from public.payment_reminders where data_label = 'fictional_demo';
  delete from public.tutor_absences where data_label = 'fictional_demo';
  delete from public.lessons where data_label = 'fictional_demo';
  delete from public.rule_suggestions where data_label = 'fictional_demo';
  delete from public.ai_activity where data_label = 'fictional_demo';
  delete from public.audit_events where data_label = 'fictional_demo';
  update public.requests set current_decision_id = null where data_label = 'fictional_demo' and current_decision_id is not null;
  delete from public.requests where data_label = 'fictional_demo';
  delete from public.policy_versions where data_label = 'fictional_demo';
  delete from public.knowledge_articles where data_label = 'fictional_demo';
  delete from public.payments where data_label = 'fictional_demo';
  delete from public.tutor_availability where data_label = 'fictional_demo';
  delete from public.bookings where data_label = 'fictional_demo';
  delete from public.families where data_label = 'fictional_demo';
  delete from public.tutors where data_label = 'fictional_demo';
  delete from public.course_offerings where data_label = 'fictional_demo';

  perform public.demo_seed();

  select jsonb_build_object(
    'requests', (select count(*) from public.requests where data_label <> 'fictional_demo'),
    'bookings', (select count(*) from public.bookings where data_label <> 'fictional_demo'),
    'lessons', (select count(*) from public.lessons where data_label <> 'fictional_demo')
  ) into v_kept;

  return jsonb_build_object(
    'resetAt', now(),
    'today', public.demo_today(),
    'lessons', (select count(*) from public.lessons where data_label = 'fictional_demo'),
    'requests', (select count(*) from public.requests where data_label = 'fictional_demo'),
    'keptNonDemo', v_kept
  );
end $$;

-- Only the server (secret key) can reset or reseed.
revoke all on function public.reset_demo_data() from public, anon, authenticated;
revoke all on function public.demo_seed() from public, anon, authenticated;
revoke all on function public.demo_today() from public, anon, authenticated;
revoke all on function public.demo_day(text, integer, date) from public, anon, authenticated;
revoke all on function public.demo_at(text, integer, time) from public, anon, authenticated;

-- ===== supabase/migrations/20261030000001_overview_hidden.sql =====
-- Requests the owner has asked to keep off the Overview's "Over to you" cards. They still
-- show on the Requests page and still count in the traffic-light totals.
-- Safe to run more than once.
alter table public.requests add column if not exists overview_hidden boolean not null default false;

-- ===== supabase/migrations/20261030000002_language_preference.sql =====
-- Each person's chosen language for the Tutor Compass interface. Null means "not chosen",
-- so the site falls back to this device's choice, then English. Only the site's own text is
-- translated; names, notes and other records are never changed.
-- Only the server writes this table (it has row level security and no public policies), and
-- the server only ever updates the signed-in person's own row.
-- Demo resets don't touch app_users, so the choice survives a reset.
-- Safe to run more than once.
alter table public.app_users add column if not exists preferred_language text;

-- The check is dropped and added again so that running this file after a new language
-- is added updates the list.
alter table public.app_users drop constraint if exists app_users_preferred_language_check;
alter table public.app_users add constraint app_users_preferred_language_check
  check (preferred_language is null or preferred_language in (
    'en', 'zh-Hans', 'ar', 'vi', 'yue-Hant', 'pa', 'el', 'it', 'hi', 'es', 'ta', 'te', 'mr', 'bn'));

-- ===== supabase/migrations/20261105000001_payments_recovery.sql =====
-- Payments and the Autonomous Payment Recovery Agent.
--
-- Billing contacts (the parent or guardian who pays), the students they pay for, their
-- invoices (as held in Xero), payment arrangements and disputes found in Gmail, and the
-- recovery agent's own records: each scan, each batch of reminder messages the owner
-- approves, every message, follow-up task, verified payment and audit event.
--
-- The rules that matter are checked here, under a lock, as well as in the app:
--   * approve_recovery_batch: only the owner approves. Every message is checked again just
--     before it goes: the invoices still have a balance, the family has no extension,
--     dispute or plan, the channel is permitted and the address isn't a duplicate.
--   * record_recovered_payment: a payment counts towards Payments Recovered only once
--     (one row per payment reference), never more than the invoice's balance, and only
--     when a reminder for that invoice was sent or simulated before the payment arrived.
--
-- Demo data is labelled 'fictional_demo' and is put back by public.reset_payments_demo(),
-- which the website calls with the main demo reset. Nothing labelled 'live_connected' or
-- 'imported' is ever removed. Safe to run more than once.

create extension if not exists pgcrypto;

-- Records ------------------------------------------------------------------------------
create table if not exists public.billing_contacts (
  id text primary key check (id ~ '^BC-[0-9A-Za-z-]{2,40}$'),
  name text not null check (char_length(name) between 1 and 120),
  email text,
  phone text,
  email_permitted boolean not null default true,
  sms_permitted boolean not null default false,
  xero_contact_id text,
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo')),
  updated_at timestamptz not null default now()
);

create table if not exists public.billing_students (
  id text primary key check (id ~ '^ST-[0-9A-Za-z-]{2,40}$'),
  name text not null check (char_length(name) between 1 and 120),
  year_level integer check (year_level between 1 and 12),
  billing_contact_id text not null references public.billing_contacts (id),
  enrolled boolean not null default true,
  -- A student is only ever messaged when this is true and the family confirmed it on the date below.
  student_contact_permitted boolean not null default false,
  student_contact_verified_on date,
  student_email text,
  student_phone text,
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo'))
);
create index if not exists billing_students_contact_idx on public.billing_students (billing_contact_id);

create table if not exists public.billing_invoices (
  id text primary key check (id ~ '^INV-[0-9A-Za-z-]{2,40}$'),
  student_id text references public.billing_students (id),
  contact_id text not null references public.billing_contacts (id),
  xero_invoice_id text,
  description text not null default '',
  amount_cents integer not null check (amount_cents > 0),
  amount_paid_cents integer not null default 0 check (amount_paid_cents >= 0),
  issued_on date not null,
  due_date date not null,
  status text not null default 'authorised' check (status in ('authorised', 'paid', 'voided')),
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo')),
  updated_at timestamptz not null default now(),
  check (amount_paid_cents <= amount_cents)
);
create index if not exists billing_invoices_contact_idx on public.billing_invoices (contact_id);

-- Extensions, disputes and payment plans. Found in Gmail by the scan, or recorded by the owner.
create table if not exists public.billing_exceptions (
  id uuid primary key default gen_random_uuid(),
  contact_id text not null references public.billing_contacts (id),
  kind text not null check (kind in ('extension', 'dispute', 'payment_plan', 'hardship')),
  source text not null default 'gmail' check (source in ('gmail', 'owner', 'sms')),
  summary text not null check (char_length(summary) <= 500),
  found_on date not null default current_date,
  active_until date,
  active boolean not null default true,
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo'))
);
create index if not exists billing_exceptions_contact_idx on public.billing_exceptions (contact_id) where active;

-- The owner's recovery rules. One row.
create table if not exists public.recovery_settings (
  id integer primary key default 1 check (id = 1),
  min_days_overdue integer not null default 7 check (min_days_overdue between 0 and 120),
  min_balance_cents integer not null default 5000 check (min_balance_cents >= 0),
  escalate_after_days integer not null default 28 check (escalate_after_days between 1 and 365),
  max_reminders integer not null default 2 check (max_reminders between 1 and 6),
  manual_minutes_per_family integer not null default 12 check (manual_minutes_per_family between 0 and 120),
  manual_minutes_per_invoice integer not null default 3 check (manual_minutes_per_invoice between 0 and 60),
  admin_hourly_rate_cents integer not null default 3800 check (admin_hourly_rate_cents >= 0),
  updated_at timestamptz not null default now()
);
insert into public.recovery_settings (id) values (1) on conflict (id) do nothing;

-- Agent records ------------------------------------------------------------------------
create table if not exists public.recovery_runs (
  id uuid primary key default gen_random_uuid(),
  started_by uuid references public.app_users (id),
  mode text not null check (mode in ('demo', 'live')),
  status text not null default 'running' check (status in ('running', 'completed', 'partial', 'failed')),
  steps jsonb not null default '[]'::jsonb,
  summary jsonb not null default '{}'::jsonb,
  assessments jsonb not null default '[]'::jsonb,
  log jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  finished_at timestamptz,
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo'))
);

create table if not exists public.recovery_batches (
  id uuid primary key default gen_random_uuid(),
  run_id uuid not null references public.recovery_runs (id) on delete cascade,
  mode text not null check (mode in ('demo', 'live')),
  status text not null default 'draft' check (status in ('draft', 'sent', 'cancelled')),
  contact_ids text[] not null,
  excluded jsonb not null default '[]'::jsonb,
  created_by uuid references public.app_users (id),
  approved_by uuid references public.app_users (id),
  approved_at timestamptz,
  version integer not null default 1,
  expires_at timestamptz not null default now() + interval '1 day',
  created_at timestamptz not null default now(),
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo'))
);

create table if not exists public.recovery_messages (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.recovery_batches (id) on delete cascade,
  contact_id text not null references public.billing_contacts (id),
  student_id text references public.billing_students (id),
  recipient_kind text not null check (recipient_kind in ('parent', 'student')),
  recipient_name text not null,
  channel text not null check (channel in ('email', 'sms')),
  address text not null,
  subject text,
  body text not null check (char_length(body) between 1 and 4000),
  invoice_ids text[] not null default '{}',
  amount_cents integer not null default 0,
  included boolean not null default true,
  edited boolean not null default false,
  status text not null default 'draft' check (status in ('draft', 'excluded', 'simulated', 'queued', 'sent', 'delivered', 'failed', 'blocked')),
  status_reason text,
  provider_ref text,
  sent_at timestamptz,
  updated_at timestamptz not null default now(),
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo')),
  -- One message per address and channel in a batch, so nobody gets the same reminder twice.
  unique (batch_id, channel, address)
);
create index if not exists recovery_messages_contact_idx on public.recovery_messages (contact_id, sent_at);

create table if not exists public.recovery_tasks (
  id uuid primary key default gen_random_uuid(),
  contact_id text not null references public.billing_contacts (id),
  kind text not null check (kind in ('reply_follow_up', 'promise_to_pay', 'escalation', 'delivery_failed')),
  summary text not null check (char_length(summary) <= 500),
  status text not null default 'open' check (status in ('open', 'done')),
  needs_owner boolean not null default false,
  source_ref text,
  created_at timestamptz not null default now(),
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo')),
  unique (contact_id, kind, source_ref)
);

create table if not exists public.recovered_payments (
  id uuid primary key default gen_random_uuid(),
  invoice_id text not null references public.billing_invoices (id),
  contact_id text not null references public.billing_contacts (id),
  payment_ref text not null unique,
  amount_cents integer not null check (amount_cents > 0),
  paid_at timestamptz not null default now(),
  verified_at timestamptz not null default now(),
  source text not null check (source in ('xero', 'demo_simulated')),
  -- The batch whose reminder came before this payment, or null when the payment can't be credited to the agent.
  batch_id uuid references public.recovery_batches (id) on delete set null,
  attributed boolean not null default false,
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo'))
);

create table if not exists public.recovery_events (
  id uuid primary key default gen_random_uuid(),
  kind text not null,
  detail text not null check (char_length(detail) <= 1000),
  mode text not null check (mode in ('demo', 'live', 'system')),
  run_id uuid references public.recovery_runs (id) on delete cascade,
  batch_id uuid references public.recovery_batches (id) on delete cascade,
  contact_id text references public.billing_contacts (id),
  invoice_id text references public.billing_invoices (id),
  actor_id uuid references public.app_users (id),
  created_at timestamptz not null default now(),
  data_label text not null default 'fictional_demo' check (data_label in ('live_connected', 'imported', 'fictional_demo'))
);
create index if not exists recovery_events_time_idx on public.recovery_events (created_at desc);

-- Only the server (secret key) reads or writes any of this.
alter table public.billing_contacts enable row level security;
alter table public.billing_students enable row level security;
alter table public.billing_invoices enable row level security;
alter table public.billing_exceptions enable row level security;
alter table public.recovery_settings enable row level security;
alter table public.recovery_runs enable row level security;
alter table public.recovery_batches enable row level security;
alter table public.recovery_messages enable row level security;
alter table public.recovery_tasks enable row level security;
alter table public.recovered_payments enable row level security;
alter table public.recovery_events enable row level security;

-- Is this family protected from reminders today? (extension, dispute, plan or hardship)
create or replace function public.billing_contact_protected(p_contact text) returns boolean
language sql stable as $$
  select exists (
    select 1 from public.billing_exceptions e
    where e.contact_id = p_contact and e.active
      and (e.active_until is null or e.active_until >= (now() at time zone 'Australia/Sydney')::date)
  )
$$;

-- Owner approval -------------------------------------------------------------------------
-- Approves a draft batch and marks each included message as it should go. p_simulated
-- means demo mode: messages become 'simulated' and nothing leaves the app. Live messages
-- become 'queued' and the server sends them and records delivery afterwards.
-- Returns the messages that will go and the ones held back, with the reason for each.
create or replace function public.approve_recovery_batch(p_batch uuid, p_actor uuid, p_version integer, p_simulated boolean)
returns jsonb
language plpgsql as $$
declare
  v_role text;
  v_batch public.recovery_batches%rowtype;
  v_msg record;
  v_reason text;
  v_balance integer;
  v_seen text[] := '{}';
  v_key text;
  v_go jsonb := '[]'::jsonb;
  v_held jsonb := '[]'::jsonb;
  v_mode text;
begin
  select role into v_role from public.app_users where id = p_actor;
  if v_role is distinct from 'owner' then
    raise exception 'forbidden: only the owner can approve and send payment reminders';
  end if;

  select * into v_batch from public.recovery_batches where id = p_batch for update;
  if not found then raise exception 'not_found: that batch no longer exists'; end if;
  if v_batch.status <> 'draft' then raise exception 'invalid_transition: this batch has already been %', v_batch.status; end if;
  if v_batch.version <> p_version then raise exception 'stale_update: the messages changed since you opened this screen. Review them again.'; end if;
  if v_batch.expires_at < now() then raise exception 'stale_update: this batch is more than a day old. Run the scan again.'; end if;
  if p_simulated and v_batch.mode <> 'demo' then raise exception 'invalid_input: a live batch cannot be simulated'; end if;
  if not p_simulated and v_batch.mode <> 'live' then raise exception 'invalid_input: demo messages can only be simulated'; end if;
  v_mode := case when p_simulated then 'demo' else 'live' end;

  -- Lock the invoices and contacts involved so nothing changes while we check.
  perform 1 from public.billing_invoices where contact_id = any (v_batch.contact_ids) for update;
  perform 1 from public.billing_contacts where id = any (v_batch.contact_ids) for update;

  for v_msg in
    select m.*, c.email_permitted, c.sms_permitted, s.student_contact_permitted, s.student_contact_verified_on
    from public.recovery_messages m
    join public.billing_contacts c on c.id = m.contact_id
    left join public.billing_students s on s.id = m.student_id
    where m.batch_id = p_batch
    order by m.recipient_kind, m.contact_id, m.channel
  loop
    v_reason := null;
    if not v_msg.included then
      v_reason := 'Left out by the owner';
    elsif public.billing_contact_protected(v_msg.contact_id) then
      v_reason := 'Family now has an extension, dispute or payment plan';
    else
      select coalesce(sum(amount_cents - amount_paid_cents), 0) into v_balance
      from public.billing_invoices
      where id = any (v_msg.invoice_ids) and status = 'authorised';
      if v_balance <= 0 then
        v_reason := 'Invoices already paid';
      elsif v_msg.recipient_kind = 'parent' and v_msg.channel = 'email' and not v_msg.email_permitted then
        v_reason := 'Email not permitted for this contact';
      elsif v_msg.recipient_kind = 'parent' and v_msg.channel = 'sms' and not v_msg.sms_permitted then
        v_reason := 'SMS not permitted for this contact';
      elsif v_msg.recipient_kind = 'student' and not (coalesce(v_msg.student_contact_permitted, false) and v_msg.student_contact_verified_on is not null) then
        v_reason := 'Student contact not verified';
      end if;
    end if;
    v_key := v_msg.channel || ':' || lower(regexp_replace(v_msg.address, '\s', '', 'g'));
    if v_reason is null and v_key = any (v_seen) then
      v_reason := 'Same address already receives a message';
    end if;

    if v_reason is null then
      v_seen := v_seen || v_key;
      update public.recovery_messages
        set status = case when p_simulated then 'simulated' else 'queued' end,
            status_reason = case when p_simulated then 'Demo mode: simulated, not sent' else null end,
            sent_at = case when p_simulated then now() else null end,
            updated_at = now()
        where id = v_msg.id;
      v_go := v_go || jsonb_build_object('id', v_msg.id, 'channel', v_msg.channel, 'contact', v_msg.contact_id);
    else
      update public.recovery_messages
        set status = case when v_msg.included then 'blocked' else 'excluded' end, status_reason = v_reason, updated_at = now()
        where id = v_msg.id;
      v_held := v_held || jsonb_build_object('id', v_msg.id, 'contact', v_msg.contact_id, 'reason', v_reason);
    end if;
  end loop;

  update public.recovery_batches
    set status = 'sent', approved_by = p_actor, approved_at = now(), version = version + 1
    where id = p_batch;

  insert into public.recovery_events (kind, detail, mode, run_id, batch_id, actor_id, data_label)
  values ('batch_approved',
          format('Owner approved %s message(s)%s; %s held back after the final check.',
                 jsonb_array_length(v_go), case when p_simulated then ' (simulated in demo mode, nothing sent)' else '' end, jsonb_array_length(v_held)),
          v_mode, v_batch.run_id, p_batch, p_actor, v_batch.data_label);

  return jsonb_build_object('go', v_go, 'held', v_held, 'mode', v_mode);
end $$;

-- Verified payments -------------------------------------------------------------------------
-- Records a payment confirmed in Xero (or, in demo mode, a simulated confirmation). It is
-- credited to the recovery agent only when a reminder covering the invoice went out (or was
-- simulated) before the payment. The same payment reference is never counted twice, and a
-- payment can't be more than what is still owed.
create or replace function public.record_recovered_payment(
  p_invoice text, p_amount_cents integer, p_payment_ref text, p_source text, p_paid_at timestamptz, p_actor uuid
) returns jsonb
language plpgsql as $$
declare
  v_inv public.billing_invoices%rowtype;
  v_balance integer;
  v_batch uuid;
  v_paid boolean;
  v_label text;
begin
  if p_amount_cents is null or p_amount_cents <= 0 then raise exception 'invalid_input: enter an amount above $0'; end if;
  if p_source not in ('xero', 'demo_simulated') then raise exception 'invalid_input: unknown payment source'; end if;
  if p_payment_ref is null or char_length(p_payment_ref) not between 3 and 120 then raise exception 'invalid_input: a payment reference is needed'; end if;

  select * into v_inv from public.billing_invoices where id = p_invoice for update;
  if not found then raise exception 'not_found: that invoice no longer exists'; end if;
  if p_source = 'demo_simulated' and v_inv.data_label <> 'fictional_demo' then
    raise exception 'forbidden: simulated payments can only be recorded against demo invoices';
  end if;

  if exists (select 1 from public.recovered_payments where payment_ref = p_payment_ref) then
    return jsonb_build_object('duplicate', true, 'counted', false);
  end if;

  v_balance := v_inv.amount_cents - v_inv.amount_paid_cents;
  if v_inv.status <> 'authorised' or v_balance <= 0 then raise exception 'invalid_input: this invoice has nothing left to pay'; end if;
  if p_amount_cents > v_balance then raise exception 'invalid_input: the payment is more than the % still owed', to_char(v_balance / 100.0, 'FM$999,990.00'); end if;

  select m.batch_id into v_batch
  from public.recovery_messages m
  join public.recovery_batches b on b.id = m.batch_id
  where p_invoice = any (m.invoice_ids)
    and m.status in ('simulated', 'sent', 'delivered')
    and coalesce(m.sent_at, b.approved_at) <= coalesce(p_paid_at, now())
  order by m.sent_at desc nulls last
  limit 1;

  v_paid := v_inv.amount_paid_cents + p_amount_cents >= v_inv.amount_cents;
  update public.billing_invoices
    set amount_paid_cents = amount_paid_cents + p_amount_cents,
        status = case when v_paid then 'paid' else status end,
        updated_at = now()
    where id = p_invoice;

  v_label := v_inv.data_label;
  insert into public.recovered_payments (invoice_id, contact_id, payment_ref, amount_cents, paid_at, source, batch_id, attributed, data_label)
  values (p_invoice, v_inv.contact_id, p_payment_ref, p_amount_cents, coalesce(p_paid_at, now()), p_source, v_batch, v_batch is not null, v_label);

  -- Stop reminders: once a family owes nothing, close their open follow-ups.
  if not exists (select 1 from public.billing_invoices where contact_id = v_inv.contact_id and status = 'authorised' and amount_paid_cents < amount_cents) then
    update public.recovery_tasks set status = 'done' where contact_id = v_inv.contact_id and status = 'open';
  end if;

  insert into public.recovery_events (kind, detail, mode, batch_id, contact_id, invoice_id, actor_id, data_label)
  values ('payment_verified',
          format('%s payment of %s verified on %s%s.%s',
                 case when v_paid then 'Full' else 'Part' end,
                 to_char(p_amount_cents / 100.0, 'FM$999,990.00'), p_invoice,
                 case when p_source = 'demo_simulated' then ' (simulated in demo mode, Xero not changed)' else ' in Xero' end,
                 case when v_batch is null then ' Not counted as recovered: no reminder had been sent first.' when v_paid then ' Reminders stopped for this invoice.' else '' end),
          case when p_source = 'demo_simulated' then 'demo' else 'live' end, v_batch, v_inv.contact_id, p_invoice, p_actor, v_label);

  return jsonb_build_object('duplicate', false, 'counted', v_batch is not null, 'fullyPaid', v_paid, 'balanceCents', v_balance - p_amount_cents);
end $$;

