insert into public.knowledge_articles (id, title, category, body, owner_approved) values ('KB-01', 'Welfare Escalation Procedure', 'welfare', '1. If a child may be in immediate danger, call 000 first.
2. Write down only what you were told, in the words used, with the date and time.
3. Do not investigate, question the child or contact the tutor about the concern.
4. Send the restricted handover to the owner straight away and phone the owner.
5. Share details only with the owner. Do not discuss it with other families or staff.
(Fictional demonstration procedure. A real business must use its own child safe policy.)', true);
insert into public.knowledge_articles (id, title, category, body, owner_approved) values ('KB-02', 'Refund Procedure', 'refund', 'Refunds are calculated on unused lessons. Under $50 the admin team may process the refund once the booking and payment are confirmed. From $50 to $200 the owner approves. Above $200 the owner decides personally. Never promise a refund before it is processed. (Fictional.)', true);
insert into public.knowledge_articles (id, title, category, body, owner_approved) values ('KB-03', 'Rescheduling Procedure', 'lesson_change', 'A lesson can be moved without a fee when the same tutor is free at the new time and the family gives at least 24 hours notice. Any fee change needs the owner. (Fictional.)', true);
insert into public.knowledge_articles (id, title, category, body, owner_approved) values ('KB-04', 'Complaints Handling', 'complaint', 'All complaints go to the owner. Acknowledge the message politely, do not admit fault or offer compensation, and tell the family the owner will be in touch. (Fictional.)', true);
insert into public.knowledge_articles (id, title, category, body, owner_approved) values ('KB-05', 'Payment Extension Procedure', 'payment_extension', 'Admin may agree to extend an unpaid invoice by up to 7 days. Longer extensions need the owner. Extensions over 30 days are payment plans and are handled by the owner. (Fictional.)', true);

-- Policies: version 1 of each, active, from the fictional demonstration rules
-- policy:refund
insert into public.policy_versions (id, category, version, status, definition, change_note, source, activated_at) values ('00000000-0000-4000-8000-000000000101', 'refund', 1, 'active', $json${"category":"refund","title":"Refund policy (fictional demo)","requiredFacts":["amount","complaint","welfare","reference","payment_record"],"rules":[{"id":"refund.under_50","label":"Small refund","range":{"min":null,"max":5000,"maxInclusive":false},"financialImpact":null,"colour":"green","permittedActions":["prepare_parent_response","prepare_admin_checklist"],"nextSteps":["Check the amount matches the unused lessons on the booking.","Process the refund in the payment system, outside Tutor Compass.","Send the parent response once the refund has actually been processed.","Record what you did on this request."],"escalation":""},{"id":"refund.50_to_200","label":"Medium refund","range":{"min":5000,"max":20000,"maxInclusive":true},"financialImpact":null,"colour":"amber","permittedActions":["prepare_parent_response","prepare_escalation_summary","send_to_owner"],"nextSteps":["Tell the family you are checking the request. Do not promise a refund.","Send the escalation summary to the owner for approval."],"escalation":"The owner approves refunds from $50 to $200."},{"id":"refund.over_200","label":"Large refund","range":{"min":20001,"max":null,"maxInclusive":true},"financialImpact":null,"colour":"red","permittedActions":["prepare_escalation_summary","send_to_owner"],"nextSteps":["Stop routine processing and do not promise a refund.","Send the request to the owner with the booking and payment history."],"escalation":"Refunds above $200 are decided by the owner only."}]}$json$::jsonb, 'Fictional demonstration rules (refund-v1) until the owner validates them.', 'seed', now());
-- policy:lesson_change
insert into public.policy_versions (id, category, version, status, definition, change_note, source, activated_at) values ('00000000-0000-4000-8000-000000000102', 'lesson_change', 1, 'active', $json${"category":"lesson_change","title":"Lesson change policy (fictional demo)","requiredFacts":["complaint","welfare","reference","financial_impact","availability"],"rules":[{"id":"lesson_change.no_fee","label":"Reschedule with no fee change","range":null,"financialImpact":"no","colour":"green","permittedActions":["prepare_parent_response","prepare_tutor_message","prepare_reschedule_proposal"],"nextSteps":["Offer the family the confirmed free time slot.","Once the family agrees, update the booking system outside Tutor Compass.","Send the tutor message and record what you did here."],"escalation":""},{"id":"lesson_change.fee_impact","label":"Change that affects fees","range":null,"financialImpact":"yes","colour":"amber","permittedActions":["prepare_parent_response","prepare_escalation_summary","send_to_owner"],"nextSteps":["Check with the owner before agreeing to any fee change."],"escalation":"The owner approves any change to fees."}]}$json$::jsonb, 'Fictional demonstration rules (lesson_change-v1) until the owner validates them.', 'seed', now());
-- policy:payment_extension
insert into public.policy_versions (id, category, version, status, definition, change_note, source, activated_at) values ('00000000-0000-4000-8000-000000000103', 'payment_extension', 1, 'active', $json${"category":"payment_extension","title":"Payment extension policy (fictional demo)","requiredFacts":["complaint","welfare","reference","extension_days","outstanding_invoice"],"rules":[{"id":"payment_extension.up_to_7","label":"Short extension","range":{"min":null,"max":7,"maxInclusive":true},"financialImpact":null,"colour":"green","permittedActions":["prepare_parent_response","prepare_admin_checklist"],"nextSteps":["Confirm the new due date with the family in writing.","Update the due date in the invoicing system, outside Tutor Compass.","Record what you did here."],"escalation":""},{"id":"payment_extension.8_to_30","label":"Longer extension","range":{"min":8,"max":30,"maxInclusive":true},"financialImpact":null,"colour":"amber","permittedActions":["prepare_parent_response","prepare_escalation_summary","send_to_owner"],"nextSteps":["Tell the family you are checking.","Send the request to the owner."],"escalation":"The owner approves extensions from 8 to 30 days."},{"id":"payment_extension.over_30","label":"Payment plan territory","range":{"min":31,"max":null,"maxInclusive":true},"financialImpact":null,"colour":"red","permittedActions":["prepare_escalation_summary","send_to_owner"],"nextSteps":["Do not agree to anything.","Send the request to the owner, who handles payment plans personally."],"escalation":"Extensions over 30 days are treated as payment plans and handled by the owner."}]}$json$::jsonb, 'Fictional demonstration rules (payment_extension-v1) until the owner validates them.', 'seed', now());

